{
  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "SOQL Injection",
      "severity": "High",
      "file": "AccountSearchController.cls",
      "lines": "searchAccounts",
      "explanation": "User input is concatenated directly into a dynamic SOQL query string, which can lead to SOQL injection.",
      "remediation": "Use bind variables or String.escapeSingleQuotes to safely include user input in SOQL queries."
    },
    {
      "category": "C2",
      "title": "CRUD/FLS Violation",
      "severity": "Medium",
      "file": "AccountSearchController.cls",
      "lines": "searchAccounts",
      "explanation": "The query does not enforce field-level security (FLS) checks, which can allow users to access fields they do not have permission to view.",
      "remediation": "Use WITH SECURITY_ENFORCED in the SOQL query to enforce FLS checks."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "CRUD/FLS violation",
      "severity": "Medium",
      "file": "ContactPhoneService.cls",
      "lines": "updatePhone",
      "explanation": "The Apex class does not enforce CRUD/FLS permissions, allowing users to update contact phone numbers even if they do not have edit permissions on the Contact object or Phone field.",
      "remediation": "Use WITH USER_MODE in the SOQL query and update the contact record as the running user to enforce CRUD/FLS permissions."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C3",
      "title": "Sharing not enforced",
      "severity": "Medium",
      "file": "CaseHistoryController.cls",
      "lines": "public without sharing class CaseHistoryController",
      "explanation": "The class is declared 'without sharing', which ignores record-level sharing rules. This can allow users to access Case records they should not see.",
      "remediation": "Change the class declaration to 'public with sharing class CaseHistoryController' to enforce record-level sharing rules."
    },
    {
      "category": "C2",
      "title": "CRUD/FLS not enforced",
      "severity": "Medium",
      "file": "CaseHistoryController.cls",
      "lines": "public static List<Case> getRecentCases()",
      "explanation": "The SOQL query does not use WITH USER_MODE or WITH SECURITY_ENFORCED, which means it ignores object and field permissions.",
      "remediation": "Add 'WITH USER_MODE' to the SOQL query to enforce CRUD and FLS checks."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C4",
      "title": "Excessive Permissions",
      "severity": "High",
      "file": "Support_Agent_Tools.permissionset-meta.xml",
      "lines": "ModifyAllData, ViewAllData",
      "explanation": "The permission set grants Modify All Data and View All Data, which are powerful system permissions that should only be granted to administrators or integration users with a clear need.",
      "remediation": "Remove Modify All Data and View All Data from the permission set unless there is a clear need for these permissions."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C5",
      "title": "Guest user exposure",
      "severity": "High",
      "file": "Catalog Site Profile.profile-meta.xml",
      "lines": "classAccesses",
      "explanation": "The PublicCatalogController class is accessible to guest users, who can call it through the Aura endpoint. This exposes the Product2 object data to unauthenticated users.",
      "remediation": "Remove PublicCatalogController from the guest profile's classAccesses, or ensure it only returns data intended to be public and enforces USER_MODE."
    },
    {
      "category": "C2",
      "title": "CRUD/FLS violation",
      "severity": "Medium",
      "file": "PublicCatalogController.cls",
      "lines": "getActiveProducts",
      "explanation": "The query does not enforce field-level security (FLS) for the Product2 object. Guest users might be able to access fields they should not.",
      "remediation": "Use WITH SECURITY_ENFORCED in the SOQL query to enforce FLS."
    }
  ]
}
